#!/bin/sh
# abcd's SessionStart hook. hooks/hooks.json runs this file with sh, so the host's
# hook-error line names this short command rather than the whole script.
[ -n "${CLAUDE_PLUGIN_ROOT:-}" ] || exit 0; r="$CLAUDE_PLUGIN_ROOT"; z=""; case "${HOME:-}" in /*) if [ -e "$HOME/.abcd" ] || [ -L "$HOME/.abcd" ]; then z=1; fi ;; esac; if [ -n "$z" ]; then if [ -f "$r/abcd" ] && [ -x "$r/abcd" ]; then i=$(cat); printf '%s' "$i" | "$r/abcd" hook session-start; e=$?; printf '%s' "$i" | "$r/abcd" hook prompt-router-reset; p=$?; [ "$e" -eq 0 ] || exit "$e"; exit "$p"; fi; if [ -e "$HOME/.abcd.noindex" ] || [ -L "$HOME/.abcd.noindex" ]; then printf '%s\n' 'abcd: Both ~/.abcd and ~/.abcd.noindex exist, so abcd has written nothing and moves neither. Keep the one you want, named ~/.abcd.noindex, and take the other out of your home folder, reconnect the working copies kept there with `find ~/.abcd.noindex/worktrees -type d -exec test -e {}/.git \; -prune -exec test -f {}/.git \; -exec git -C {} worktree repair \;` (each `repair: gitdir incorrect` line it prints is a link it fixed), then run abcd again.' >&2; else printf '%s\n' 'abcd: abcd'\''s folder is now ~/.abcd.noindex, a name the Mac'\''s search indexer passes over, and ~/.abcd still stands, so abcd has written nothing. Rename it with `mv ~/.abcd ~/.abcd.noindex`, reconnect the working copies kept there with `find ~/.abcd.noindex/worktrees -type d -exec test -e {}/.git \; -prune -exec test -f {}/.git \; -exec git -C {} worktree repair \;` (each `repair: gitdir incorrect` line it prints is a link it fixed), then run abcd again.' >&2; fi; exit 2; fi; b=''; s=0; if [ -x "$CLAUDE_PLUGIN_ROOT/hooks/bootstrap.sh" ]; then : > "$r/.bootstrap.attempt" 2>/dev/null || true; b=$("$CLAUDE_PLUGIN_ROOT/hooks/bootstrap.sh" 2>&1 >/dev/null </dev/null); s=$?; fi; [ -z "$b" ] || printf '%s\n' "$b" >&2; if [ -f "$CLAUDE_PLUGIN_ROOT/abcd" ] && [ -x "$CLAUDE_PLUGIN_ROOT/abcd" ]; then g="$CLAUDE_PLUGIN_ROOT/abcd"; x=""; case "${HOME:-}" in /*) if [ -e "$HOME/.abcd.noindex/dogfood-roots" ] || [ -L "$HOME/.abcd.noindex/dogfood-roots" ]; then x=$("$g" hook dogfood-binary </dev/null); case "$x" in /*) [ -f "$x" ] && [ -x "$x" ] || x="" ;; *) x="" ;; esac; fi ;; esac; i=$(cat); if [ -n "$x" ]; then o=$(printf '%s' "$i" | "$x" hook session-start); e=$?; if [ $e -eq 0 ]; then [ -z "$o" ] || printf '%s\n' "$o"; else echo "abcd: the dogfood build FAILED TO RUN hook session-start (exit $e), so the installed release runs it instead" >&2; printf '%s' "$i" | "$g" hook session-start; e=$?; fi; else printf '%s' "$i" | "$g" hook session-start; e=$?; fi; if [ -n "$x" ]; then o=$(printf '%s' "$i" | "$x" hook prompt-router-reset); p=$?; if [ $p -eq 0 ]; then [ -z "$o" ] || printf '%s\n' "$o"; else echo "abcd: the dogfood build FAILED TO RUN hook prompt-router-reset (exit $p), so the installed release runs it instead" >&2; printf '%s' "$i" | "$g" hook prompt-router-reset; p=$?; fi; else printf '%s' "$i" | "$g" hook prompt-router-reset; p=$?; fi; [ "$s" -eq 0 ] || exit "$s"; [ "$e" -eq 0 ] || exit "$e"; exit "$p"; fi; [ -n "$b" ] || printf '%s\n' "abcd: the plugin binary is not installed, so the rule loader did not reset and the session-start checks did not run — hooks/bootstrap.sh provisions it at session start; start a session with network access, or install per https://github.com/intentdriven/abcd#install" >&2; [ "$s" -eq 0 ] || exit "$s"; exit 2
